#include <vector>
using namespace std;

class Solution {
public:
    int numberOfEffectiveSubsequences(vector<int>& nums) {
        long long MOD = 1000000007;
        long long dp0 = 0, dp1 = 0;
        for (int x : nums) {
            if (x % 2 == 0) {
                dp0 = (dp0 + dp1 + 1) % MOD;
            } else {
                dp1 = (dp1 + dp0 + 1) % MOD;
            }
        }
        return (dp0 + dp1) % MOD;
    }
};

